typedef struct Reader {
    long (*read)(struct Reader *self, void *buf, long n);
    void (*close)(struct Reader *self);
} Reader;
typedef struct { Reader iface; Reader *inner; unsigned long long bytes; } Counting;
static long counting_read(Reader *self, void *buf, long n) {
    Counting *c = (Counting *)self;               /* iface must stay the first member */
    long got = c->inner->read(c->inner, buf, n);  /* delegate to the wrapped reader */
    c->bytes += got > 0 ? (unsigned long long)got : 0;
    return got;
}
Counting *counting_new(Reader *inner);            /* fills iface entries and inner */
